<script module lang="ts">
/**
 * Table with sorting, selection, pagination, loading and empty states (`design/components/data-table.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/data-table.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import {
  Render,
  agentMember,
  bindSnippet,
  joinSlot,
  watchEffect,
  type RenderNode,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/data-table.module.css'
import Button from '../controls/Button.svelte'
import Checkbox from '../controls/Checkbox.svelte'
import EmptyState from './EmptyState.svelte'
import Inline from '../layout/Inline.svelte'
import Skeleton from './Skeleton.svelte'
import Table from './Table.svelte'
import TableBody from './TableBody.svelte'
import TableCell from './TableCell.svelte'
import TableHead from './TableHead.svelte'
import TableHeader from './TableHeader.svelte'
import TableRow from './TableRow.svelte'
import type { EmptyStateProps } from './EmptyState.svelte'
import type { SortDirection } from './Table.svelte'

export interface DataTableColumn<Row> {
  key: string
  header: string
  /** Defaults to `String(row[key])`, the common case. */
  cell?: Snippet<[Row]>
  sortable?: boolean
  numeric?: boolean
}

export interface DataTableSort {
  key: string
  direction: SortDirection
}

export interface DataTableRowDetail<Row> {
  row: Row
  /**
   * Closes this row's detail. When focus is inside the detail it moves to the row's
   * disclosure first, because a focused element that leaves the page leaves focus on
   * the page itself. It does nothing for a row that is not open.
   */
  close: () => void
}

export interface DataTableMessages {
  /** The bulk bar's count. */
  selected: (count: number) => string
  selectAll: string
  /** The row checkbox's name when `getRowLabel` is not supplied. */
  selectRow: string
  /**
   * Names a row's disclosure, from what `getRowName` returns for the row, and names
   * the expansion column's header, called with `undefined`. Optional, so messages
   * written for a table without `rowDetail` still type-check.
   */
  detailsLabel?: (rowName: string | undefined) => string
}

export interface DataTableProps<Row> {
  /**
   * Shown only while something is selected.
   */
  bulkActions?: Snippet
  columns: DataTableColumn<Row>[]
  data: Row[]
  /**
   * The rows open at first, while the table holds the set. The set keeps the id of a row that
   * leaves `data`, so a row that comes back with its page is still open.
   */
  defaultExpanded?: ReadonlySet<string>
  /**
   * Required, because a list without a designed empty state has a bug.
   */
  emptyState: EmptyStateProps
  /**
   * The open rows by id. Controlled when given; without it the table holds the set.
   */
  expanded?: ReadonlySet<string>
  getRowId: (row: Row) => string
  /**
   * The whole name of a row's checkbox ("Select Invoice 12"), so a screen reader does not hear
   * "Select row" on every row. Only the checkbox reads it.
   */
  getRowLabel?: (row: Row) => string
  /**
   * The row's own name ("Invoice 12"). `messages.detailsLabel` names the row's disclosure from
   * it ("Details for Invoice 12"). It is not `getRowLabel`, which is a whole control's name: a
   * disclosure named from it would read "Details for Select Invoice 12".
   */
  getRowName?: (row: Row) => string
  /**
   * Whether a row has a detail. A row it refuses has an empty cell in the expansion column and
   * never draws a detail row, whatever `expanded` holds. A function that draws cannot report
   * that it drew nothing, so the table asks this before it draws the disclosure. Without it
   * every row has one.
   */
  isRowExpandable?: (row: Row) => boolean
  label: string
  loading?: boolean
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: DataTableMessages
  /**
   * Called with the next set of open rows, controlled or not.
   */
  onExpandedChange?: (next: ReadonlySet<string>) => void
  /**
   * Opens the row. Per the "row `interactive` handlers" rule in `data-table.md`, a click on the
   * checkbox selects and does *not* open.
   */
  onRowClick?: (row: Row) => void
  onSelectionChange?: (next: ReadonlySet<string>) => void
  onSortChange?: (sort: DataTableSort) => void
  /**
   * A `Pagination` or a `CursorPagination`, rendered below the table.
   */
  pagination?: Snippet
  /**
   * Passing it turns expansion on: each row gets a disclosure, and an open row draws what this
   * returns in a full-width row under itself. It takes one object, so every renderer hands the
   * same named values, `row` and `close`. A detail closes itself with `close`: a caller that
   * only removes the id from `expanded` while focus is inside the detail leaves focus on the
   * page.
   */
  rowDetail?: Snippet<[DataTableRowDetail<Row>]>
  /**
   * Passing it turns selection on, even as an empty set.
   */
  selection?: ReadonlySet<string>
  /**
   * Controlled; the type allows exactly one sorted column.
   */
  sort?: DataTableSort
  stickyHeader?: boolean
}
</script>

<script lang="ts" generics="Row">
let {
  bulkActions,
  columns,
  data,
  defaultExpanded,
  emptyState,
  expanded,
  getRowId,
  getRowLabel,
  getRowName,
  isRowExpandable,
  label: labelOwn,
  loading = false,
  messages = (() => ({
    selected: (count: number) => `${count} selected`,
    selectAll: 'Select all',
    selectRow: 'Select row',
  }))(),
  onExpandedChange,
  onRowClick,
  onSelectionChange,
  onSortChange,
  pagination,
  rowDetail,
  selection,
  sort,
  stickyHeader,
}: DataTableProps<Row> = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const listening = {
  get expandedChange() {
    return onExpandedChange !== undefined
  },
  get rowClick() {
    return onRowClick !== undefined
  },
  get selectionChange() {
    return onSelectionChange !== undefined
  },
  get sortChange() {
    return onSortChange !== undefined
  },
}
const slots = {
  get bulkActions() {
    return bulkActions
  },
  get pagination() {
    return pagination
  },
  get rowDetail() {
    return rowDetail
  },
}
// svelte-ignore state_referenced_locally
let ownExpanded = $state(defaultExpanded ?? new Set<string>())
let root = $state<HTMLElement | null>(null)
const selectable = $derived(selection !== undefined)
const expandable = $derived(slots.rowDetail)
const open = $derived(expanded ?? ownExpanded)
const canExpand = $derived((row: Row): boolean => isRowExpandable?.(row) ?? true)
const detailsLabel = $derived(
  messages.detailsLabel ??
    ((rowName: string | undefined): string =>
      rowName === undefined ? 'Details' : `Details for ${rowName}`),
)
const span = $derived(columns.length + (selectable ? 1 : 0) + 1)
const ids = $derived(data.map((row) => getRowId(row)))
const selectedCount = $derived(selection?.size ?? 0)
const selectedHere = $derived(ids.filter((id) => selection?.has(id)).length)
const allSelected = $derived(selectable && ids.length > 0 && selectedHere === ids.length)
const someSelected = $derived(selectedHere > 0 && !allSelected)
const headerChecked = $derived(allSelected ? true : someSelected ? 'indeterminate' : false)
const bar = $derived(selectable && selectedCount > 0)
const empty = $derived(!loading && data.length === 0)
const skeletons = $derived(Array.from({ length: 5 }, (_, index) => index))
const cellOf = $derived((column: DataTableColumn<Row>, row: Row): RenderNode | string => {
  if (column.cell !== undefined) return bindSnippet(column.cell, row)
  const value = (row as Record<string, unknown>)[column.key]
  return value === undefined || value === null ? '' : String(value)
})
const sortTo = $derived((column: DataTableColumn<Row>): DataTableSort => ({
  key: column.key,
  direction: sort?.key === column.key && sort?.direction === 'asc' ? 'desc' : 'asc',
}))
const toggleAll = $derived(() => {
  if (selection === undefined) return
  const next = new Set(selection)
  for (const id of ids) {
    if (allSelected) next.delete(id)
    else next.add(id)
  }
  onSelectionChange?.(next)
})
const toggleRow = $derived((id: string) => {
  if (selection === undefined) return
  const next = new Set(selection)
  if (next.has(id)) next.delete(id)
  else next.add(id)
  onSelectionChange?.(next)
})
const toggleExpanded = $derived((id: string) => {
  const next = new Set(open)
  if (next.has(id)) next.delete(id)
  else next.add(id)
  ownExpanded = next
  onExpandedChange?.(next)
})
const closeDetail = $derived((id: string) => {
  if (!open.has(id)) return
  const element = root as HTMLElement | null
  const detailId = CSS.escape(`${uid}-detail-${ids.indexOf(id)}`)
  if (element?.querySelector(`#${detailId}`)?.matches(':focus-within') === true)
    element.querySelector<HTMLElement>(`[aria-controls="${detailId}"]`)?.focus()
  const next = new Set(open)
  next.delete(id)
  ownExpanded = next
  onExpandedChange?.(next)
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'DataTable',
    element: () => root,
    state: () => ({
      'sort-key': sort?.key ?? null,
      'sort-direction': sort?.direction ?? '',
      columns: columns.map((column) => ({
        id: column.key,
        label: column.header,
        ...(column.sortable === true ? {} : { disabled: true }),
      })),
      selection: [...(selection ?? [])],
      expanded: [...open],
      loading: loading,
    }),
    actions: {
      'sort-ascending': {
        argument: 'id',
        run: (value) =>
          (sort?.key === value && sort?.direction === 'asc') ||
          onSortChange?.({ key: value, direction: 'asc' }),
      },
      'sort-descending': {
        argument: 'id',
        run: (value) =>
          (sort?.key === value && sort?.direction === 'desc') ||
          onSortChange?.({ key: value, direction: 'desc' }),
      },
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    class={styles.table}
    data-loading={(loading) ? '' : undefined}
    data-empty={(empty) ? '' : undefined}
    aria-busy={(loading) ? true : undefined}
    data-member="data-table"
    >{#if bar
      }<div class={styles.bulkBar}
        ><Inline gap={4} align="center" justify="between" wrap={true}
          ><span class={styles.bulkCount} aria-live="polite"
            >{messages.selected(selectedCount)
          }</span
          >{#if slots.bulkActions
            }<Inline gap={3} align="center" wrap={true}>{@render bulkActions?.()}</Inline
          >{/if
        }</Inline
      ></div
    >{/if
    }{#if empty
      }{#snippet actionOfEmptyState1()}<Render node={emptyState.action} />{/snippet
      }{#snippet secondaryActionOfEmptyState2()
        }<Render node={emptyState.secondaryAction}
      />{/snippet
      }<EmptyState
        icon={emptyState.icon}
        title={emptyState.title}
        description={emptyState.description}
        action={emptyState.action !== undefined ? actionOfEmptyState1 : undefined}
        secondaryAction={emptyState.secondaryAction !== undefined ? secondaryActionOfEmptyState2 : undefined}
    />{:else
      }<Table {label} caption={label} {stickyHeader} grid={true} multiselectable={selectable}
        ><TableHead
          ><TableRow
            >{#if selectable
              }<TableHeader
                ><Checkbox
                  aria-label={messages.selectAll}
                  checked={headerChecked}
                  disabled={loading || ids.length === 0}
                  onCheckedChange={() => { toggleAll() }}
              /></TableHeader
            >{/if
            }{#if expandable
              }<TableHeader
                ><span class={styles.expandLabel} data-undrawn="">{detailsLabel(undefined)}</span
              ></TableHeader
            >{/if
            }{#each columns as column (column.key)
              }<TableHeader
                numeric={column.numeric}
                sortable={column.sortable}
                sortDirection={sort?.key === column.key ? sort?.direction : undefined}
                onSort={() => { if (column.sortable) onSortChange?.(sortTo(column)) }}
                >{column.header
              }</TableHeader
            >{/each
          }</TableRow
        ></TableHead
        ><TableBody
          >{#if loading
            }{#each skeletons as index (`skeleton-${index}`)
              }<TableRow
                >{#if selectable}<TableCell><Skeleton shape="circle" size={4} /></TableCell>{/if
                }{#if expandable}<TableCell><Skeleton shape="circle" size={4} /></TableCell>{/if
                }{#each columns as column (column.key)
                  }<TableCell numeric={column.numeric}><Skeleton textStep="sm" /></TableCell
                >{/each
              }</TableRow
            >{/each
          }{:else
            }{#each data as row, index (getRowId(row))
              }<TableRow
                selected={selection?.has(getRowId(row))}
                interactive={listening.rowClick}
                onClick={() => { if (listening.rowClick) onRowClick?.(row) }}
                >{#if selectable
                  }<TableCell
                    ><span
                      class={styles.selectCell}
                      onclick={(event) => { event.stopPropagation() }}
                      ><Checkbox
                        aria-label={getRowLabel?.(row) ?? messages.selectRow}
                        checked={selection?.has(getRowId(row)) ?? false}
                        onCheckedChange={() => { toggleRow(getRowId(row)) }}
                    /></span
                  ></TableCell
                >{/if
                }{#if expandable
                  }<TableCell
                    >{#if canExpand(row)
                      }<span
                        class={styles.expandCell}
                        onclick={(event) => { event.stopPropagation() }}
                        ><Button
                          variant="ghost"
                          tone="neutral"
                          size="sm"
                          iconOnly={true}
                          icon={canExpand(row) && open.has(getRowId(row)) ? 'up' : 'down'}
                          label={detailsLabel(getRowName?.(row))}
                          expanded={canExpand(row) && open.has(getRowId(row))}
                          aria-controls={canExpand(row) && open.has(getRowId(row)) ? `${uid}-detail-${index}` : undefined}
                          onClick={() => { toggleExpanded(getRowId(row)) }}
                      /></span
                    >{/if
                  }</TableCell
                >{/if
                }{#each columns as column (column.key)
                  }<TableCell numeric={column.numeric}
                    >{#if typeof cellOf(column, row) === 'string'
                      }{cellOf(column, row)
                    }{:else
                      }<Render node={cellOf(column, row)}
                    />{/if
                  }</TableCell
                >{/each
              }</TableRow
              >{#if expandable && canExpand(row) && open.has(getRowId(row))
                }<tr id={`${uid}-detail-${index}`} data-detail=""
                  ><td class={styles.detailCell} colspan={span}
                    ><div class={styles.detail}
                      >{@render rowDetail?.({ row: row, close: () => closeDetail(getRowId(row)) })
                    }</div
                  ></td
                ></tr
              >{/if
            }{/each
          }{/if
        }</TableBody
      ></Table
    >{/if
    }{#if slots.pagination
      }<div class={styles.pagination}
        ><Inline gap={3} justify="end" wrap={true}>{@render pagination?.()}</Inline
      ></div
    >{/if
  }</div
>{/if
}{@render joined.end?.()}
